// Generated by Cake from commit 49739b87ee3b62ae0e1c6fe47040e078482b217d.
// Persistent row-caching cluster Softmax (the 8-tile variants, C = 8 and 16):
// the grid holds at most one cluster per row and no more clusters than are
// resident; cluster k of n walks rows k, k + n, ... Each CTA copies its chunk
// of the next row into shared memory with one 1D bulk copy per tile, and the
// buffer turns over tile by tile: right after a tile of the current row is
// written, every thread reads the next row's copy of that tile, frees its slot
// for the row after and exponentiates it. On sm_100a a 16-CTA cluster that
// walks more than 24 rows refills its buffer a row at a time instead, once the
// row is read. The exchange is the row-caching family's push.
//
// Raw generated payload identities (the sm_100a and sm_103a renders are
// identical except where both are listed; such a variant keeps its sm_103a
// kernel under __CUDA_ARCH__ == 1030):
//   c8_t8 (85145 bytes):
//     sha256:83e179366186418716caa5f965e2ae394e9a1243b4aa1e1b13ffbf16a6d69389
//   c16_t8 sm_100a (163887 bytes):
//     sha256:6e9f311f6ab84eed001a61d84f834a2e9f19a7647450fd2b6c6163d336854672
//   c16_t8 sm_103a (85162 bytes):
//     sha256:c6e464792959e34b7c3c583d6418f1896a693568b8937dd448852a5d4c665945
// Integration replaces the generated integer typedefs and the unused
// tensor-map and bf16/fp8 declarations with <stdint.h>, keeps the
// generated helpers once and each variant's macros around its kernel,
// and adds sm_103a-only PDL device control (bit 2 of parameter_kind) and
// a CUDA <12.9 2x128-bit fallback for the 256-bit inline-PTX accesses.

// clang-format off
#include <stdint.h>

#include <math_constants.h>

__device__ __forceinline__ int make_warp_uniform(int x) {
    int result;
    asm volatile("shfl.sync.idx.b32 %0, %1, 0, 0x1F, 0xFFFFFFFF;"
                 : "=r"(result) : "r"(x));
    return result;
}

__device__ __forceinline__ uint32_t elect_sync() {
    uint32_t pred = 0;
    asm volatile(
        "{\n\t"
        ".reg .pred %%px;\n\t"
        "elect.sync _|%%px, %1;\n\t"
        "@%%px mov.s32 %0, 1;\n\t"
        "}\n"
        : "+r"(pred)
        : "r"(0xFFFFFFFF));
    return pred;
}

__device__ __forceinline__ void mbarrier_init(int mbar_addr, int count) {
    asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;"
        :: "r"(mbar_addr), "r"(count) : "memory");
}

// CTA-local pipelines have short, resident producer/consumer edges.  Omitting
// suspendTimeHint keeps a miss on the lightweight TRYWAIT retry path; the
// explicit loop still makes this helper blocking until acquire succeeds.
__device__ __forceinline__ void mbarrier_wait(int mbar_addr, int phase) {
    asm volatile(
        "{\n\t"
        ".reg .pred P1;\n\t"
        "LAB_WAIT:\n\t"
        "mbarrier.try_wait.parity.acquire.cta.shared::cta.b64"
        " P1, [%0], %1;\n\t"
        "@P1 bra.uni DONE;\n\t"
        "bra.uni LAB_WAIT;\n\t"
        "DONE:\n\t"
        "}\n"
        :: "r"(mbar_addr), "r"(phase) : "memory");
}

__device__ __forceinline__ void mbarrier_arrive(int mbar_addr) {
    asm volatile(
        "mbarrier.arrive.release.cta.shared::cta.b64 _, [%0];"
        :: "r"(mbar_addr) : "memory");
}

__device__ __forceinline__ void mbarrier_arrive_expect_tx(int mbar_addr, uint32_t bytes) {
    asm volatile(
        "mbarrier.arrive.expect_tx.release.cta.shared::cta.b64 _, [%0], %1;"
        :: "r"(mbar_addr), "r"(bytes) : "memory");
}

__device__ __forceinline__ float approx_exp2(float x) {
    float y;
    asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(y) : "f"(x));
    return y;
}

__device__ __forceinline__ float approx_rcp(float x) {
    float y;
    asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(y) : "f"(x));
    return y;
}

__device__ __forceinline__ float max_noftz(float a, float b) {
    float c;
    asm("max.f32 %0, %1, %2;" : "=f"(c) : "f"(a), "f"(b));
    return c;
}

__device__ __forceinline__ void cp_async_bulk_gmem2smem(
    unsigned smem_addr, const void* gmem_ptr, unsigned bytes, int mbar_addr) {
    asm volatile(
        "cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes"
        " [%0], [%1], %2, [%3];"
        :: "r"(smem_addr), "l"(gmem_ptr), "r"(bytes), "r"(mbar_addr)
        : "memory");
}

